package edu.facilities.ui;
import edu.facilities.model.*; import edu.facilities.service.*; import javafx.fxml.*; import javafx.collections.*; import javafx.scene.control.*; import java.sql.*;
public class RoomsController { @FXML private TableView<Room> roomsTable; @FXML private TableColumn<Room,String> codeColumn,nameColumn,typeColumn,statusColumn; @FXML private TableColumn<Room,Integer> capacityColumn; @FXML private TextField searchField; @FXML private ComboBox<String> typeFilter,statusFilter; @FXML private Label messageLabel;
 @FXML public void initialize(){codeColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getId()));nameColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getName()));typeColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getType().name()));capacityColumn.setCellValueFactory(x->new javafx.beans.property.SimpleIntegerProperty(x.getValue().getCapacity()).asObject());statusColumn.setCellValueFactory(x->new javafx.beans.property.SimpleStringProperty(x.getValue().getStatus().name()));typeFilter.getItems().addAll("ALL","CLASSROOM","LAB");statusFilter.getItems().addAll("ALL","AVAILABLE","OCCUPIED","MAINTENANCE");typeFilter.setValue("ALL");statusFilter.setValue("ALL");load();}
 @FXML private void filter(){load();} private void load(){try{var all=new RoomService().getAllRooms();String q=searchField.getText().toLowerCase();roomsTable.setItems(FXCollections.observableArrayList(all.stream().filter(r->(q.isBlank()||r.toString().toLowerCase().contains(q))&&(typeFilter.getValue().equals("ALL")||r.getType().name().equals(typeFilter.getValue()))&&(statusFilter.getValue().equals("ALL")||r.getStatus().name().equals(statusFilter.getValue()))).toList()));messageLabel.setText(roomsTable.getItems().size()+" room(s)");}catch(SQLException e){messageLabel.setText(e.getMessage());}}
}
